app_batch.code:
const steps = await device.batch([
  { name: 'app_tap', arguments: { target: 'text=Network & internet' } },
  { name: 'app_wait_for', arguments: { target: 'text=Internet' } },
])
for (const step of steps) console.log(step.name, step.text)

app_devices.code:
for (const d of await device.devices()) {
  console.log(d.id, d.platform, d.model, d.emulator ? 'emulator' : 'hardware')
}

app_map.code:
const elements = await device.map()
for (const e of elements) console.log(e.ref, e.role, e.label)
// @e1 button Network & internet ...

app_screen.code:
await device.screen('small-phone')
// ... run the flow ...
await device.screen('reset')

app_source.code:
import { writeFileSync } from 'node:fs'
const { source } = await device.source()
writeFileSync('screen.xml', String(source))

app_storage.code:
import { writeFileSync } from 'node:fs'
const state = await device.storage()
writeFileSync('state.json', JSON.stringify(state))

start.code:
import { start } from 'mobium'
const device = await start()
try {
  console.log(device.session?.platform, device.session?.driver)
} finally {
  await device.quit()
}

errorFrom.code:
import { errorFrom, NoSuchElementError } from 'mobium'
const err = errorFrom('no element matches text=Sign in', { code: 'no_such_element', remedy: 'run app_map' })
console.log(err instanceof NoSuchElementError, err.remedy)

quit.code:
try {
  await device.tap('text=Network & internet')
} finally {
  await device.quit()
}

MobiumError.code:
import { MobiumError } from 'mobium'
try {
  await device.tap('text=Sign in')
} catch (e) {
  if (!(e instanceof MobiumError)) throw e
  console.log(e.code, e.remedy, e.retryable, e.details)
}

NoSuchElementError.code:
import { NoSuchElementError } from 'mobium'
try {
  await device.tap('text=Skip')
} catch (e) {
  if (!(e instanceof NoSuchElementError)) throw e // no Skip button this time
}

TimedOutError.code:
import { TimedOutError } from 'mobium'
try {
  await device.waitFor('text=Welcome back', { timeoutMs: 5000 })
} catch (e) {
  if (e instanceof TimedOutError) console.log(e.message) // what was on screen instead
  else throw e
}

UnsupportedError.code:
import { UnsupportedError } from 'mobium'
try {
  await device.press('back')
} catch (e) {
  if (!(e instanceof UnsupportedError)) throw e
  console.log(e.remedy) // iOS has no back button
}

intro.code:
import { start } from 'mobium'

const device = await start({ platform: 'android', app: 'com.android.settings' })
for (const el of await device.map()) console.log(el.ref, el.label)
await device.quit()
